    57	    /**
    58	     * @return The counters representing population numbers.
    59	     */
    60	    public Map<Class<? extends Actor>, Counter> getCounters(Field field)
    61	    {
    62	        if (!areCountsValid) generateCounts(field);
    63	        return counters;
    64	    }
    65	    
    66	    /**
    67	     * Invalidate the current set of statistics; reset all 
    68	     * counts to zero.
    69	     */
    70	    public void reset()
    71	    {
    72	        areCountsValid = false;
    73	        
    74	        for (Counter count : counters.values())
    75	        {
    76	            count.reset();
    77	        }
    78	    }
    79	
    80	    /**
    81	     * Increment the count for one class of actor.
    82	     * 
    83	     * @param actorClass The class of actor to increment.
    84	     */
    85	    public void incrementCount(Class<? extends Actor> actorClass)
    86	    {
    87	        Counter count = counters.get(actorClass);
    88	        
    89	        if (count == null)
    90	        {
    91	            // We do not have a counter for this species yet.
    92	            // Create one:
    93	            count = new Counter(actorClass.getName());
    94	            
    95	            counters.put(actorClass, count);
    96	        }
    97	        
    98	        count.increment();
    99	    }
