   106	    /**
   107	     * Determine whether the simulation is still viable.
   108	     * I.e., should it continue to run.
   109	     * 
   110	     * @return True if there is more than one species alive.
   111	     */
   112	    public boolean isViable(Field field)
   113	    {
   114	        // How many counts are non-zero:
   115	        int nonZero = 0;
   116	        
   117	        if (!areCountsValid) generateCounts(field);
   118	        
   119	        for (Counter info : counters.values())
   120	        {
   121	            if (info.getCount() > 0) nonZero++;
   122	        }
   123	        
   124	        return nonZero > 1;
   125	    }
