   127	    /**
   128	     * Generate counts of the number of actors.
   129	     * These are not kept up to date as actors are placed in the
   130	     * field, but only when a request is made for the information.
   131	     * 
   132	     * @param field The field to generate the stats for.
   133	     */
   134	    private void generateCounts(Field field)
   135	    {
   136	        reset();
   137	        
   138	        for (int row = 0; row < field.getDepth(); row++)
   139	        {
   140	            for (int col = 0; col < field.getWidth(); col++)
   141	            {
   142	                Actor actor = field.getActorAt(row, col);
   143	                
   144	                if (actor != null) incrementCount(actor.getClass());
   145	            }
   146	        }
   147	        
   148	        areCountsValid = true;
   149	    }
