   259	     * The configured probabilities are applied in order, while using a single
   260	     * random draw to preserve the existing overall distribution.
   261	     *
   262	     * @param location The field location being populated.
   263	     * @param random   The shared random number generator.
   264	     * @return A new actor for the location, or null if it remains empty.
   265	     */
   266	    private Actor createInitialActor(Location location, Random random)
   267	    {
   268	        double selection = random.nextDouble();
   269	        double cumulativeProbability = 0.0;
   270	        double remainingProbability = 1.0;
   271	
   272	        for (SpawnRule rule : INITIAL_POPULATION_RULES)
   273	        {
   274	            double effectiveProbability = remainingProbability * rule.creationProbability;
   275	            cumulativeProbability += effectiveProbability;
   276	
   277	            if (selection <= cumulativeProbability)
   278	            {
   279	                return rule.factory.create(field, location);
   280	            }
   281	
   282	            remainingProbability -= effectiveProbability;
   283	        }
   284	
   285	        return null;
   286	    }
