    25	public class StatisticsView extends Application
    26	{
    27	    // Constants representing the JavaFX window properties:
    28	    //   The default size of the window:
    29	    private static final int WINDOW_WIDTH = 800;
    30	    private static final int WINDOW_HEIGHT = 600;
    31	    //   The default title of the window:
    32	    private static final String WINDOW_TITLE = "Statistics";
    33	    
    34	    // Constants representing JavaFX GUI components:
    35	    //   The root layout component:
    36	    private static BorderPane root;
    37	    //   An informational label explaining the window:
    38	    private static Label infoLabel;
    39	    //   The line chart showing populations:
    40	    private static LineChart<Number, Number> lineChart;
    41	    //   The axes of the population line chart:
    42	    private static NumberAxis xAxis, yAxis;
    43	    //   The XYSeries representing each population over time:
    44	    private static final Map<Class<? extends Actor>, Series<Number, Number>> actorXYSeries = new HashMap<>();
    45	    
    46	    // The time between updates for the stats:
    47	    private static final double UPDATE_TIME_IN_SECONDS = 0.1;
    48	    // The last day recorded:
    49	    private static int lastDayRecorded = -1; // Set to -1 so we record day 0
    50	    // The highest recorded population:
    51	    private static int highestPopulation = 0;
    52	    
    53	    /**
    54	     * @param stage The stage (window) for JavaFX.
    55	     */
    56	    @Override
    57	    public void start(Stage stage)
    58	    {
    59	        // Create the root layout component:
    60	        root = new BorderPane();
    61	        
    62	        // Create the scene:
    63	        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);
    64	        
    65	        // Create the informational label:
    66	        infoLabel = new Label("The chart below shows the population of each species over time:");
    67	        
    68	        // Create the line chart:
    69	        lineChart = getPopulationLineChart();
    70	        lineChart.setAnimated(false);
    71	        
    72	        // Set the initial properties of the root BorderPane:
    73	        final int ROOT_PADDING = 5;
    74	        root.setTop(infoLabel);
    75	        root.setCenter(lineChart);
    76	        root.setPadding(new Insets(ROOT_PADDING, ROOT_PADDING, ROOT_PADDING, ROOT_PADDING));
    77	        
    78	        // Set the initial properties of the stage and show it:
    79	        stage.setScene(scene);
    80	        stage.setTitle(WINDOW_TITLE);
    81	        stage.show();
    82	        
    83	        // Create a timeline to update the population line chart at a fixed rate:
    84	        KeyFrame keyFrame = new KeyFrame(Duration.millis(UPDATE_TIME_IN_SECONDS * 1000), e -> updatePopulationLineChart());
    85	        Timeline timeline = new Timeline(keyFrame);
    86	        timeline.setCycleCount(Timeline.INDEFINITE);
    87	        timeline.play();
    88	    }
    89	    
    90	    /**
    91	     * Create a line chart for the population.
    92	     * 
    93	     * @return A line chart representing population.
    94	     */
    95	    private static LineChart<Number, Number> getPopulationLineChart()
    96	    {
    97	        // Create the axes:
    98	        final int xAxisStep = 5;
    99	        final int yAxisStep = 1000;
   100	        xAxis = new NumberAxis(0, 0, xAxisStep);
   101	        yAxis = new NumberAxis(0, 0, yAxisStep);
   102	        xAxis.setLabel("Days");
   103	        yAxis.setLabel("Population");
   104	        
   105	        // Create the line chart itself:
   106	        return new LineChart<>(xAxis, yAxis);
   107	    }
   108	    
   109	    /**
   110	     * Update the data for the population line chart. This is called
   111	     * periodically.
   112	     */
   113	    private void updatePopulationLineChart()
   114	    {
   115	        // Reset if necessary:
   116	        if (Simulator.resetStatisticsView)
   117	        {
   118	            resetPopulationLineChart();
   119	            Simulator.resetStatisticsView = false;
   120	        }
   121	        
   122	        // Guard statement: Don't continue with this if the day
   123	        // hasn't changed since the last update:
   124	        if (lastDayRecorded == TimeSystem.getCurrentDay()) return;
   125	        
   126	        // Iterate through each counter in FieldStats:
   127	        Field field = Simulator.getCurrentField();
   128	        Map<Class<? extends Actor>, Counter> counters = Simulator.getFieldStats().getCounters(field);
   129	        
   130	        for (Map.Entry<Class<? extends Actor>, Counter> entry : counters.entrySet())
   131	        {
   132	            Class<? extends Actor> actorType = entry.getKey();
   133	            Counter counter = entry.getValue();
   134	            
   135	            // Get the new data to add to the XYSeries:
   136	            Data<Number, Number> newData = new XYChart.Data<>(TimeSystem.getCurrentDay(), counter.getCount());
   137	            
   138	            // Create a new XYSeries for this actor if there is none already:
   139	            if (!actorXYSeries.containsKey(actorType))
   140	            {
   141	                Series<Number, Number> series = new XYChart.Series<>();
   142	                series.setName(counter.getName());
   143	                
   144	                lineChart.getData().add(series);
   145	                
   146	                actorXYSeries.put(actorType, series);
   147	            }
   148	            
   149	            // Update the XYSeries for this Actor:
   150	            Series<Number, Number> series = actorXYSeries.get(actorType);
   151	            series.getData().add(newData); 
   152	            
   153	            // Update the highest population if necessary:
   154	            if (counter.getCount() > highestPopulation) highestPopulation = counter.getCount();
   155	        }
   156	        
   157	        // Set the new last day recorded:
   158	        lastDayRecorded = TimeSystem.getCurrentDay();
   159	        
   160	        // Set the upper bounds for each of the axes:
   161	        xAxis.setUpperBound(TimeSystem.getCurrentDay());
   162	        yAxis.setUpperBound(highestPopulation);
   163	    }
   164	    
   165	    /**
   166	     * Reset the population line chart.
   167	     */
   168	    public static void resetPopulationLineChart()
   169	    {
   170	        lineChart = getPopulationLineChart();
   171	        root.setCenter(lineChart);
   172	        
   173	        lineChart.getData().clear();
   174	        
   175	        actorXYSeries.clear();
   176	        
   177	        lastDayRecorded = -1;
   178	        
   179	        highestPopulation = 0;
   180	    }
   181	}
